{
  "items": [
    {
      "name": "Polynomial.modByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.coeff_modByMonic_mem_pow_natDegree_mul",
      "module_name": "Mathlib.Algebra.Polynomial.CoeffMem",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} {S : Type u_3} [inst : CommRing R] [inst_1 : Ring S] [inst_2 : Algebra R S] (p q : Polynomial S)\n  (Mp : Submodule R S),\n  (∀ (i : ℕ), p.coeff i ∈ Mp) →\n    1 ∈ Mp →\n      ∀ (Mq : Submodule R S), (∀ (i : ℕ), q.coeff i ∈ Mq) → 1 ∈ Mq → ∀ (i : ℕ), (p %ₘ q).coeff i ∈ Mq ^ p.natDegree * Mp"
    },
    {
      "name": "Polynomial.divModByMonicAux",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → Polynomial R → {q : Polynomial R} → q.Monic → Polynomial R × Polynomial R"
    },
    {
      "name": "Polynomial.sum_modByMonic_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R},\n  q.Monic → ∀ {n : ℕ}, q.degree ≤ ↑n → ∑ i, (Polynomial.monomial ↑i) ((p %ₘ q).coeff ↑i) = p %ₘ q"
    },
    {
      "name": "Polynomial.modByMonic_eq_sub_mul_div",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p : Polynomial R) {q : Polynomial R}, q.Monic → p %ₘ q = p - q * (p /ₘ q)"
    },
    {
      "name": "Polynomial.mod",
      "module_name": "Mathlib.Algebra.Polynomial.FieldDivision",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Field R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.coeff_divModByMonicAux_mem_span_pow_mul_span",
      "module_name": "Mathlib.Algebra.Polynomial.CoeffMem",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} {S : Type u_3} [inst : CommRing R] [inst_1 : Ring S] [inst_2 : Algebra R S] (p q : Polynomial S)\n  (hq : q.Monic) (i : ℕ),\n  (p.divModByMonicAux hq).1.coeff i ∈\n      (1 ⊔ Submodule.span R (Set.range q.coeff)) ^ p.natDegree * (1 ⊔ Submodule.span R (Set.range p.coeff)) ∧\n    (p.divModByMonicAux hq).2.coeff i ∈\n      (1 ⊔ Submodule.span R (Set.range q.coeff)) ^ p.natDegree * (1 ⊔ Submodule.span R (Set.range p.coeff))"
    },
    {
      "name": "Polynomial.natDegree_modByMonic_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p : Polynomial R) {q : Polynomial R}, q.Monic → q ≠ 1 → (p %ₘ q).natDegree < q.natDegree"
    }
  ]
}
